/**
 * Every shared stylesheet a gallery demo needs, in cascade order. The
 * generated lazy wrappers (scripts/prepare-gallery.mjs) import this
 * statically, so a styleguide page links its CSS in the HTML while the demo
 * JS still loads on demand; otherwise the server-rendered demos would paint
 * unstyled until their chunk arrived.
 */
import './mantine-styles';
import '@mantine/dates/styles.css';
import '@mantine/tiptap/styles.css';
// Both generated by scripts/prepare-gallery.mjs (run by dev/build).
import './app-globals.scoped.css';
import './gallery.module.css';
